function run(generatorFunc) {
  const gen = generatorFunc();
  function step(val) {
    const { value, done } = gen.next(val);
    if (done) return Promise.resolve(value);
    return Promise.resolve(value).then(step, err => gen.throw(err));
  }
  return step();
}

